   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/

// refer: https://www.youtube.com/c/lewislepton

let mySize;

// a shader variable
let theShader;

function preload(){
	theShader = createShader(vert, frag)
}

function setup() {
	mySize = max(windowWidth, windowHeight);
  // shaders require WEBGL mode to work
  // createCanvas(mySize, mySize/16*11, WEBGL);
  createCanvas(mySize, mySize, WEBGL);
  noStroke();
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

  // shader() sets the active shader with our shader
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_frame", frameCount/2.0);
	theShader.setUniform("u_time", frameCount * 0.25);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/10.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)/10.0]);

  // rect gives us some geometry on the screen
  rect(0,0,width, height);
}

function windowResized(){
  resizeCanvas(windowWidth, windowHeight);
}

function keyPressed() {
	//noLoop();
	saveCanvas("Shaders_002_2022", "png");
}

// === Tab: frag ===
//noprotect
const frag = `
#ifdef GL_ES
precision highp float;
#endif

uniform float u_time;
uniform vec2 u_mouse;
uniform vec2 u_resolution;

void main(){
  // vec2 coord = (gl_FragCoord.xy / u_resolution);
  vec2 coord = (gl_FragCoord.xy * 1. - u_resolution) / min(u_resolution.x, u_resolution.y);
  vec3 color = vec3(0.0);

  float angle = atan(-coord.y * 2., coord.x * 2.) * 2.;
  // float len = length(coord - vec2(${Math.random()*0.35+1.0}, ${Math.random()*0.35+1.0}));
  float len = length(coord);

  color.r += 1.5 * sin(len * 25.0 + floor(angle * u_mouse.x / 10.) + u_time *  ${Math.random()*0.25+0.6} + 0.05);
  color.g -= 1.5 * cos(len * 25.0 + floor(angle * 5.0) + u_time *  ${Math.random()*0.35+0.6} + 0.1);
  color.b += 1.5 * sin(len * 25.0 + floor(angle * 5.0) + u_time *  ${Math.random()*0.15+0.6} + 0.2);

  gl_FragColor = vec4(color, 1.0);
}
`

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

